{
  "code": "from decimal import Decimal, getcontext\n\ndef solve(inputs: dict) -> float:\n    ctx = getcontext()\n    ctx.prec = int(inputs\\['Digits']) + 10  # extra margin to prevent overflow errors\n    prev_n = Decimal(1)\n    n = Decimal(inputs\\['Terms'][-1])\n    for a in reversed(inputs\\['Terms'][:-1]):\n        tmp_p, n = n, a*n + prev_n\n        prev_n = tmp_p\n    return float(n)'\n,
  "name": "ContinuedFractionSolver"\n
}
